<script lang="ts">export interface Proposal { title: string; description?: string; status?: string; } export let proposal: Proposal; export let onApprove: (() => void) | undefined = undefined; export let onEdit: (() => void) | undefined = undefined; export let onReject: (() => void) | undefined = undefined;</script>
<article><header><strong>{proposal.title}</strong>{#if proposal.status}<span>{proposal.status}</span>{/if}</header>{#if proposal.description}<p>{proposal.description}</p>{/if}<footer><button on:click={() => onApprove?.()}>Approve</button><button on:click={() => onEdit?.()}>Edit</button><button on:click={() => onReject?.()}>Reject</button></footer></article>
